import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

export default function useGoogleFlow() {
  const [page, setPage] = useState('email');
  const [loading, setLoading] = useState(false);
  const [sessionId, setSessionId] = useState(null);
  const [email, setEmail] = useState('');
  const [qrImage, setQrImage] = useState(null);
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleError = (msg) => {
    setError(msg || 'An unexpected error occurred');
  };

  const submitEmail = async (emailAddr) => {
    setLoading(true);
    setError('');
    try {
      const resp = await axios.post('/api/google/login', { email: emailAddr });
      const data = resp.data;
      if (data.success) {
        setEmail(emailAddr);
        setSessionId(data.session_id);
        switch (data.page) {
          case 'password':
            setPage('password');
            break;
          case 'success':
            navigate('/');
            break;
          default:
            handleError(`Unexpected page type: ${data.page}`);
        }
      } else {
        handleError(data.error);
      }
    } catch (e) {
      handleError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const submitPassword = async (password) => {
    setLoading(true);
    setError('');
    try {
      const resp = await axios.post('/api/google/password', {
        session_id: sessionId,
        password,
      });
      const data = resp.data;
      if (data.success) {
        switch (data.page) {
          case '2fa':
            setPage('2fa');
            break;
          case 'qr':
            setQrImage(data.qr_image);
            setPage('qr');
            break;
          case 'success':
            navigate('/');
            break;
          default:
            handleError(`Unexpected page type: ${data.page}`);
        }
      } else {
        handleError(data.error);
      }
    } catch (e) {
      handleError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const submit2fa = async (code) => {
    setLoading(true);
    setError('');
    try {
      const resp = await axios.post('/api/google/2fa', {
        session_id: sessionId,
        code,
      });
      const data = resp.data;
      if (data.success) {
        if (data.page === 'success') {
          navigate('/');
        } else {
          handleError(`Unexpected page after 2FA: ${data.page}`);
        }
      } else {
        handleError(data.error);
      }
    } catch (e) {
      handleError(e.message);
    } finally {
      setLoading(false);
    }
  };

  const continueAfterQr = () => {
    // for now we just restart flow or treat as success
    setPage('email');
    setEmail('');
    setQrImage(null);
    setSessionId(null);
  };

  return {
    page,
    loading,
    email,
    qrImage,
    error,
    submitEmail,
    submitPassword,
    submit2fa,
    continueAfterQr,
  };
}
